      +     'var url="https://github.com/"+repo+"/issues/new?labels=feedback&title="+encodeURIComponent("Reviewer feedback: "+INV)+"&body="+encodeURIComponent(body);'
      +     'var w=window.open(url,"_blank","noopener");if(!w)location.href=url;'
